// AdminServiceHandler is an implementation of the shepherd.mgmt.v1.AdminService service.
type AdminServiceHandler interface {
	ListOrgs(context.Context, *connect.Request[v1.ListOrgsRequest]) (*connect.Response[v1.ListOrgsResponse], error)
	CreateOrg(context.Context, *connect.Request[v1.CreateOrgRequest]) (*connect.Response[v1.Org], error)
	UpdateOrg(context.Context, *connect.Request[v1.UpdateOrgRequest]) (*connect.Response[v1.Org], error)
	DeleteOrg(context.Context, *connect.Request[v1.DeleteOrgRequest]) (*connect.Response[v1.DeleteOrgResponse], error)
	// AddOrgTenant gives an org an exact tenant or a tenant prefix. App admin
	// only. An exact tenant is unique across all orgs; a prefix may not
	// overlap another org's prefix nor cover another org's exact tenant, and
	// neither may cover a tenant another org's destination or binding sends.
	AddOrgTenant(context.Context, *connect.Request[v1.AddOrgTenantRequest]) (*connect.Response[v1.Org], error)
	// RemoveOrgTenant takes an exact tenant or prefix away from an org. App
	// admin only. Refused (failed_precondition, naming each one) when a live
	// tenant route, destination or destination binding of the org would be left
	// on a tenant no remaining tenant or prefix of the org covers, and for the
	// default while another exact tenant could become the default.
	RemoveOrgTenant(context.Context, *connect.Request[v1.RemoveOrgTenantRequest]) (*connect.Response[v1.Org], error)
	// SetDefaultOrgTenant makes one of the org's exact tenants its default.
	// App admin only.
	SetDefaultOrgTenant(context.Context, *connect.Request[v1.SetDefaultOrgTenantRequest]) (*connect.Response[v1.Org], error)
	// SetOrgStrictTenants turns an org's strict tenant mode on or off. App
	// admin only. In strict mode every destination, destination binding and
	// tenant route of the org must use a tenant the org owns, and pipeline text
	// that sets a literal tenant the org does not own fails validation.
	// Turning it on is refused (failed_precondition) when the org owns no
	// tenant, or while a destination, binding, live route or enabled pipeline
	// of the org would break the rule — the message lists each one, and
	// TenantPreflight returns them as data.
	SetOrgStrictTenants(context.Context, *connect.Request[v1.SetOrgStrictTenantsRequest]) (*connect.Response[v1.Org], error)
	// TenantPreflight reports what would break the strict tenant rule. App
	// admin only, read-only. With org_id set it checks that org (what
	// SetOrgStrictTenants would refuse over); empty checks every org, as the
	// server-wide tenants.require_owned setting would at boot.
	TenantPreflight(context.Context, *connect.Request[v1.TenantPreflightRequest]) (*connect.Response[v1.TenantPreflightResponse], error)
	// ListOrgImportRepositories lists the repositories an org's pipelines may
	// import modules from in strict tenant mode, with import.git pinned to a
	// full commit SHA. App admin only.
	ListOrgImportRepositories(context.Context, *connect.Request[v1.ListOrgImportRepositoriesRequest]) (*connect.Response[v1.ListOrgImportRepositoriesResponse], error)
	// AddOrgImportRepository allows an org's pipelines to import.git from a
	// repository, pinned to a full commit SHA; strict tenant mode fetches the
	// module and lints its content. App admin only. The URL must be an
	// https://, http://, ssh:// or git@host:path git remote; it is stored with
	// its normal form, which a pipeline's repository must match
	// (invalid_argument for an ambiguous spelling, already_exists for a second
	// spelling of an entry). credential_id optionally names one of the org's
	// git credentials, for a private repository.
	AddOrgImportRepository(context.Context, *connect.Request[v1.AddOrgImportRepositoryRequest]) (*connect.Response[v1.OrgImportRepository], error)
	// RemoveOrgImportRepository takes a repository off an org's allowlist. App
	// admin only. Refused (failed_precondition, naming each one) while the
	// strict tenant rule applies to the org and an enabled pipeline imports
	// from it.
	RemoveOrgImportRepository(context.Context, *connect.Request[v1.RemoveOrgImportRepositoryRequest]) (*connect.Response[v1.RemoveOrgImportRepositoryResponse], error)
	// ListOrgStrictComponents lists the components an app admin allowed for an
	// org although strict tenant mode refuses them (refused or unclassified in
	// the schema overlay). App admin only.
	ListOrgStrictComponents(context.Context, *connect.Request[v1.ListOrgStrictComponentsRequest]) (*connect.Response[v1.ListOrgStrictComponentsResponse], error)
	// AddOrgStrictComponent allows one component for an org in strict tenant
	// mode. It lifts only the refusal of an unclassified or refused component:
	// every other strict check still applies to it, and it is shown as
	// admin-allowed and unreviewed. App admin only; invalid_argument for a
	// name that is not a component name or a component strict mode already
	// accepts, already_exists for one already allowed.
	AddOrgStrictComponent(context.Context, *connect.Request[v1.AddOrgStrictComponentRequest]) (*connect.Response[v1.OrgStrictComponent], error)
	// RemoveOrgStrictComponent takes a component off an org's list. App admin
	// only. Refused (failed_precondition, naming each one) while the strict
	// tenant rule applies to the org and an enabled pipeline uses the
	// component.
	RemoveOrgStrictComponent(context.Context, *connect.Request[v1.RemoveOrgStrictComponentRequest]) (*connect.Response[v1.RemoveOrgStrictComponentResponse], error)
	ListClusters(context.Context, *connect.Request[v1.ListClustersRequest]) (*connect.Response[v1.ListClustersResponse], error)
	ClaimCluster(context.Context, *connect.Request[v1.ClaimClusterRequest]) (*connect.Response[v1.ClaimClusterResponse], error)
	UnclaimCluster(context.Context, *connect.Request[v1.UnclaimClusterRequest]) (*connect.Response[v1.UnclaimClusterResponse], error)
	// Agent tokens are bound to an organisation (and optionally narrowed to
	// cluster/role allowlists). An org admin lists, creates and revokes the
	// tokens bound to their own org; an app admin sees every token, including
	// unbound ones, and is the only caller who may bind or rebind one.
	ListAgentTokens(context.Context, *connect.Request[v1.ListAgentTokensRequest]) (*connect.Response[v1.ListAgentTokensResponse], error)
	CreateAgentToken(context.Context, *connect.Request[v1.CreateAgentTokenRequest]) (*connect.Response[v1.CreateAgentTokenResponse], error)
	RevokeAgentToken(context.Context, *connect.Request[v1.RevokeAgentTokenRequest]) (*connect.Response[v1.RevokeAgentTokenResponse], error)
	// BindAgentToken sets a live token's org and allowlists in place. The
	// secret is unchanged, so collectors keep their credentials. App admin only.
	BindAgentToken(context.Context, *connect.Request[v1.BindAgentTokenRequest]) (*connect.Response[v1.AgentToken], error)
	// Collector OIDC identity bindings (docs/archive/plans/2026-09-16-agent-oidc-auth.md):
	// map a collector's OIDC identity (issuer + app id) to an organisation.
	ListAgentIdentities(context.Context, *connect.Request[v1.ListAgentIdentitiesRequest]) (*connect.Response[v1.ListAgentIdentitiesResponse], error)
	CreateAgentIdentity(context.Context, *connect.Request[v1.CreateAgentIdentityRequest]) (*connect.Response[v1.AgentIdentity], error)
	DeleteAgentIdentity(context.Context, *connect.Request[v1.DeleteAgentIdentityRequest]) (*connect.Response[v1.DeleteAgentIdentityResponse], error)
	SearchGroups(context.Context, *connect.Request[v1.SearchGroupsRequest]) (*connect.Response[v1.SearchGroupsResponse], error)
	// OIDC single sign-on configuration. Available only when the Helm chart did
	// NOT configure an issuer: chart config always wins, and GetOidcSettings
	// says so through `source` and `editable` rather than by hiding the values,
	// so an admin looking at a chart-managed deployment can still see what it is
	// pointed at.
	GetOidcSettings(context.Context, *connect.Request[v1.GetOidcSettingsRequest]) (*connect.Response[v1.OidcSettings], error)
	UpdateOidcSettings(context.Context, *connect.Request[v1.UpdateOidcSettingsRequest]) (*connect.Response[v1.OidcSettings], error)
	// TestOidcSettings performs OIDC discovery against a candidate
	// configuration WITHOUT storing it, so an admin can find a wrong issuer
	// before turning sign-in over to it. A read by the capability
	// classification's naming rule (it mutates nothing), and deliberately so.
	TestOidcSettings(context.Context, *connect.Request[v1.TestOidcSettingsRequest]) (*connect.Response[v1.TestOidcSettingsResponse], error)
	DeleteOidcSettings(context.Context, *connect.Request[v1.DeleteOidcSettingsRequest]) (*connect.Response[v1.DeleteOidcSettingsResponse], error)
	// ListOidcProviderPresets returns the built-in provider catalogue the
	// settings form prefills from. Served by the backend rather than hardcoded
	// in the UI so the defaults the server applies on save and the defaults the
	// form shows cannot drift apart.
	ListOidcProviderPresets(context.Context, *connect.Request[v1.ListOidcProviderPresetsRequest]) (*connect.Response[v1.ListOidcProviderPresetsResponse], error)
}

